<?php
require __DIR__.'/app/bootstrap.php';$user=require_permission('view_all_tickets');$id=positive_id($_GET,'id');require_ticket_visible($user,$id);
$ticket=query('SELECT t.*,d.name department_name,u.full_name assignee_name,c.full_name creator_name FROM tickets t JOIN departments d ON d.id=t.department_id LEFT JOIN users u ON u.id=t.assignee_id JOIN users c ON c.id=t.created_by WHERE t.id=? AND t.deleted_at IS NULL',[$id])->fetch();if(!$ticket){http_response_code(404);exit('Ticket not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();try{
        $action=input('action',20);
        if($action==='comment'){
            require_permission('comment_tickets');$body=input('body',10000);if($body==='')throw new InvalidArgumentException('Write a comment first.');db()->beginTransaction();query('INSERT INTO ticket_comments(ticket_id,user_id,body) VALUES(?,?,?)',[$id,$user['id'],$body]);activity($id,(int)$user['id'],'comment_added');db()->commit();flash('Comment added.');
        }elseif($action==='update'){
            require_permission('edit_tickets');$status=input('status',20);$priority=input('priority',20);$resolution=input('resolution',20000);$assignee=positive_id($_POST,'assignee_id');
            if(!isset(TICKET_STATUSES[$status]) || !isset(TICKET_PRIORITIES[$priority]))throw new InvalidArgumentException('Select a valid status and priority.');
            if($assignee && !in_array($assignee,array_map('intval',array_column(active_users(),'id')),true))throw new InvalidArgumentException('Select an active assignee.');
            if($status==='closed' && $resolution==='')throw new InvalidArgumentException('Add a resolution before closing the ticket.');
            if($status!=='closed' && $resolution!=='')throw new InvalidArgumentException('Select Closed to save a resolution, or clear the resolution to keep the ticket open.');
            db()->beginTransaction();$old=query('SELECT * FROM tickets WHERE id=? FOR UPDATE',[$id])->fetch();
            if((int)$old['version']!==positive_id($_POST,'version'))throw new InvalidArgumentException('This ticket changed. Reload before saving your update.');
            if(($old['status']==='closed' || $status==='closed') && !user_can('close_tickets')){db()->rollBack();http_response_code(403);exit('You cannot close or reopen tickets.');}
            if($assignee!==(int)$old['assignee_id'] && !user_can('assign_tickets')){db()->rollBack();http_response_code(403);exit('You cannot change the assignee.');}
            $closed=$status==='closed'?($old['closed_at']?:date('Y-m-d H:i:s')):null;
            query('UPDATE tickets SET status=?,priority=?,assignee_id=?,resolution=?,closed_at=?,version=version+1 WHERE id=?',[$status,$priority,$assignee?:null,$resolution?:null,$closed,$id]);sync_ticket_assignees($id,$assignee?[$assignee]:[]);activity($id,(int)$user['id'],'updated',['before'=>array_intersect_key($old,array_flip(['status','priority','assignee_id','resolution'])),'after'=>['status'=>$status,'priority'=>$priority,'assignee_id'=>$assignee,'resolution'=>$resolution]]);db()->commit();flash('Ticket updated.');
        }else throw new InvalidArgumentException('Unknown ticket action.');
        redirect('ticket.php?id='.$id);
    }catch(InvalidArgumentException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
$total=(int)query('SELECT COUNT(*) FROM ticket_activity WHERE ticket_id=?',[$id])->fetchColumn();$page=page_number($total);
$entries=query('SELECT a.*,u.full_name actor_name FROM ticket_activity a LEFT JOIN users u ON u.id=a.actor_id WHERE ticket_id=? ORDER BY a.id DESC LIMIT 25 OFFSET '.(($page-1)*25),[$id])->fetchAll();
$comments=query('SELECT c.*,u.full_name FROM ticket_comments c JOIN users u ON u.id=c.user_id WHERE ticket_id=? ORDER BY c.id DESC LIMIT 50',[$id])->fetchAll();
$v=fn($key)=>$_SERVER['REQUEST_METHOD']==='POST' && request_string($_POST,'action')==='update'?request_string($_POST,$key):(string)($ticket[$key]??'');
page_start('Ticket '.$ticket['ticket_number'],$user);?><a class="back-link" href="index.php">← Tickets</a><?php error_notice($error);?><section class="panel"><div class="section-head"><h2><?=e($ticket['subject'])?></h2><span class="badge <?=e($ticket['status'])?>"><?=e(TICKET_STATUSES[$ticket['status']])?></span></div><dl class="profile-facts"><div><dt>Employee</dt><dd><?php if(user_can('view_staff')):?><a href="employee.php?id=<?=$ticket['staff_id']?>"><?=e($ticket['employee_name'])?></a><?php else:echo e($ticket['employee_name']);endif;?></dd></div><div><dt>Department</dt><dd><?=e($ticket['department_name'])?></dd></div><div><dt>Category</dt><dd><?=e($ticket['category'])?></dd></div><div><dt>Assigned to</dt><dd><?=e($ticket['assignee_name']??'Unassigned')?></dd></div><div><dt>Created by</dt><dd><?=e($ticket['creator_name'])?></dd></div><div><dt>Created</dt><dd><?=e($ticket['created_at'])?></dd></div></dl><h3>Attachments</h3><?php $files=query('SELECT id,original_name,file_size FROM ticket_attachments WHERE ticket_id=? AND file_data IS NOT NULL ORDER BY id',[$id])->fetchAll(); if(!$files):?><p class="muted">No attachments.</p><?php else:?><ul><?php foreach($files as $file):?><li><a href="attachment.php?id=<?=(int)$file['id']?>"><?=e($file['original_name'])?></a> (<?=number_format($file['file_size']/1024,1)?> KB)</li><?php endforeach;?></ul><?php endif;?><h3>Issue</h3><p class="preserve-lines"><?=e($ticket['issue'])?></p><?php if($ticket['resolution']):?><h3>Resolution</h3><p class="preserve-lines"><?=e($ticket['resolution'])?></p><?php endif;?></section><div class="split"><div><section class="panel"><h2>Conversation</h2><?php if(user_can('comment_tickets')):?><form method="post"><?php csrf_field();?><input type="hidden" name="action" value="comment"><label>Add a comment<textarea name="body" rows="3" maxlength="10000" required><?=e(request_string($_POST,'body'))?></textarea></label><div class="form-footer"><button class="button">Post comment</button></div></form><?php endif;?><p class="muted">Latest 50 comments</p><?php foreach($comments as $comment):?><article class="timeline-item"><h3><?=e($comment['full_name'])?></h3><small><?=e($comment['created_at'])?></small><p><?=e($comment['body'])?></p></article><?php endforeach;if(!$comments):?><p class="muted">No comments yet.</p><?php endif;?></section><section class="panel"><h2>Ticket history</h2><?php foreach($entries as $entry):?><article class="timeline-item"><h3><?=e(ucfirst(str_replace('_',' ',$entry['action'])))?></h3><small><?=e($entry['actor_name']??'System')?> · <?=e($entry['created_at'])?></small><?php $details=json_decode($entry['details']??'{}',true);if(isset($details['before'],$details['after'])):?><ul class="changes"><?php foreach($details['after'] as $field=>$value):if((string)($details['before'][$field]??'')===(string)$value)continue;?><li><?=e(ucfirst(str_replace('_',' ',$field)))?>: <?=e((string)($details['before'][$field]??'—'))?> → <?=e((string)$value)?></li><?php endforeach;?></ul><?php endif;?></article><?php endforeach;pagination($total,$page);?></section></div><?php if(user_can('edit_tickets')):?><section class="panel" style="align-self:start"><h2>Update ticket</h2><form method="post"><?php csrf_field();?><input type="hidden" name="action" value="update"><input type="hidden" name="version" value="<?=e($v('version'))?>"><label>Status<select name="status"><?php enum_options(TICKET_STATUSES,$v('status'));?></select></label><label>Priority<select name="priority"><?php enum_options(TICKET_PRIORITIES,$v('priority'));?></select></label><label>Assigned to<select name="assignee_id"><option value="">Unassigned</option><?php options(active_users(),$v('assignee_id'),'full_name');?></select></label><label>Resolution (required to close)<textarea name="resolution" rows="5" maxlength="20000"><?=e($v('resolution'))?></textarea></label><div class="form-footer"><button class="button">Save changes</button></div></form></section><?php endif;?></div><?php page_end();
